import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./boxes-Q12yMsyh.js";import{C as n,D as r,E as i,M as a,N as o,O as s,P as c,S as l,T as u,_ as d,k as f,v as p,x as m}from"./shared-DP9JVsk0.js";import{t as h}from"./key-round-D-Q1K68g.js";import{t as g}from"./CodeEditor-BZlrvoTL.js";var _=`data:image/svg+xml;base64,`,v=`data:image/svg+xml;base64,`,y=e();function b({module:e}){return(0,y.jsxs)(o,{children:[(0,y.jsx)(a,{variant:`project`,chip:e??`Блок 11 · Валидация и CRUD Planner API`,title:`59. JSON-хранилище и серверные идентификаторы`,intro:`POST уже создаёт задачу, а TaskRead задаёт вид ответа. Теперь проследим, где задача действительно сохраняется, кто назначает её id и как проверить, что API и CLI работают с одним Planner.`,tags:[{icon:(0,y.jsx)(t,{size:14}),label:`настоящее сохранение`},{icon:(0,y.jsx)(h,{size:14}),label:`серверный id`}]}),(0,y.jsxs)(c,{number:`00`,title:`Успешный ответ должен соответствовать сохранённому состоянию`,children:[(0,y.jsx)(s,{children:`В предыдущем занятии мы описали отдельные формы запроса и ответа. Теперь проследим, что успешный POST изменяет в общем Planner и где подтвердим этот результат.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`Persistent Planner уже имеет Task, PlannerService, JsonStorage и CLI. В предыдущем занятии API получило отдельные схемы входа и ответа.`},{title:`Новый вопрос`,description:`Как доказать, что успешный POST изменил общий файл, а не только вернул красивый JSON?`},{title:`Результат`,description:`Проследим готовый путь add_task, проверим id и подтвердим чтение той же записи новым сервисом и CLI.`}]}),(0,y.jsx)(s,{children:`В предыдущем занятии мы разделили вход и ответ. Но схема ответа сама ничего не сохраняет. В этом занятии не будем писать второе хранилище или ещё один генератор id. Проследим, как уже работающий Planner создаёт задачу и где подтверждается её постоянное сохранение.`})]}),(0,y.jsxs)(c,{number:`01`,title:`Один POST проходит через готовое ядро`,children:[(0,y.jsx)(s,{children:`Разберём путь одной задачи. Здесь важно отделить HTTP-обработчик от предметного действия и от работы с файлом.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Вход`,description:`FastAPI принимает проверенный TaskCreate с title и priority.`},{title:`Действие`,description:`Маршрут передаёт эти значения существующему PlannerService.add_task().`},{title:`Состояние`,description:`Сервис загружает Task, применяет правила Planner и назначает серверный id.`},{title:`Сохранение`,description:`JsonStorage переводит Task в прежний формат JSON и записывает общий файл.`},{title:`Ответ`,description:`Сервис возвращает Task, а API формирует публичный TaskRead и статус 201.`}]}),(0,y.jsx)(`p`,{children:`Схема запроса не создаёт задачу. Она только проверяет вход. Предметное действие выполняет сервис, а постоянную запись в прежнем формате создаёт хранилище. Публичный ответ появляется после успешного сохранения.`}),(0,y.jsx)(`p`,{children:`На схеме проследим один настоящий маршрут от запроса до общего файла и назад к тому же клиенту. Стрелка ответа начинается у API только после того, как сервис закончил сохранение.`}),(0,y.jsxs)(`figure`,{className:`lesson-infographic lesson-infographic--lesson59`,children:[(0,y.jsxs)(`picture`,{children:[(0,y.jsx)(`source`,{media:`(max-width: 640px)`,srcSet:v}),(0,y.jsx)(`img`,{src:_,alt:`POST проходит от клиента через API и PlannerService к JsonStorage, которое читает и сохраняет общий JSON-файл. После сохранения API возвращает тому же клиенту ответ 201 с TaskRead.`,width:`1672`,height:`836`,loading:`lazy`,decoding:`async`})]}),(0,y.jsx)(`figcaption`,{children:`Один запрос проходит через существующий сервис и общий файл; ответ уходит тому же клиенту.`})]}),(0,y.jsx)(`p`,{children:`TaskCreate похожа на заполненную форму выдачи читательского билета: форма задаёт, какие сведения сообщил человек, но сама не создаёт запись в каталоге. PlannerService применяет правила и назначает номер, JsonStorage сохраняет полную задачу, а TaskRead описывает выданный клиенту ответ. Граница аналогии: TaskRead является схемой данных, а не физическим билетом и не командой сохранения.`}),(0,y.jsx)(`p`,{children:`В предыдущем занятии TaskRead намеренно не включала tags: публичный ответ и сохранённая доменная запись решают разные задачи. Сервис передаёт в JsonStorage полную Task, поэтому сериализация сохраняет и поля, которых нет в HTTP-ответе. Если сохранить только TaskRead, часть состояния исчезнет при следующем чтении файла. Поэтому ниже сверим tags после загрузки новым сервисом.`}),(0,y.jsx)(`p`,{children:`Посмотрим на ту же последовательность в независимом примере. Это обычный Python-фрагмент, а не код Planner.`}),(0,y.jsx)(p,{code:`def add_book(title, storage):
    books = storage.load()
    book = {"title": title}
    books.append(book)
    storage.save(books)
    return book`,steps:[{line:0,note:`Функция получает предметное значение и объект, который умеет загружать и сохранять состояние.`},{line:1,note:`До изменения функция получает текущее состояние. Новое действие не должно начинаться с пустого списка.`,vars:{books:`текущие записи`}},{line:2,note:`Создаётся новая запись. В Planner такую работу выполняет доменная модель и правило сервиса.`,vars:{book:`{'title': ...}`}},{line:4,note:`Новое состояние передаётся storage. Если запись не удалась, следующая строка с return не будет достигнута.`,vars:{books:`старые записи + новая запись`}},{line:5,note:`Только после успешного save функция возвращает результат вызывающему коду.`,vars:{result:`созданная запись`}}]}),(0,y.jsx)(i,{tone:`info`,children:`Для Planner название и приоритет приходят из TaskCreate, но id назначает существующий сервис. Форму ответа затем ограничивает TaskRead. Ни одна из этих схем не заменяет save().`})]}),(0,y.jsxs)(c,{number:`02`,title:`Как отличить файл от состояния одного процесса`,children:[(0,y.jsx)(s,{children:`Список Python можно прочитать повторно, пока жив процесс. Это ещё не доказывает, что данные переживут его завершение.`}),(0,y.jsx)(`p`,{children:`В предыдущем курсе мы уже построили JsonStorage с load() и save(). Его назначение здесь не нужно изобретать заново. Нужно проверить, что точка сборки CLI и API выбирает один и тот же путь к файлу.`}),(0,y.jsx)(g,{caption:`две точки входа, одна настроенная сборка`,code:`CLI → build_service() ─┐
                       ├→ PlannerService → JsonStorage → data/tasks.json
API → build_service() ─┘`}),(0,y.jsx)(`p`,{children:`Файл задаёт общее постоянное состояние. Два отдельных процесса не делят переменные Python, но могут последовательно читать и менять один файл через одинаковую настройку.`}),(0,y.jsx)(`p`,{children:`Одного имени data/tasks.json недостаточно, чтобы доказать общий файл: относительный путь разрешается от текущей рабочей папки. CLI и API могут запускаться из разных каталогов и с тем же именем попасть в разные файлы. Сверим фактический путь, который получает build_service(). Разные экземпляры PlannerService ожидаемы; общий Python-объект между процессами для этого не нужен.`}),(0,y.jsx)(`p`,{children:`Представим двух сотрудников с отдельными столами и общей картотекой. Записи на столе похожи на данные, оставшиеся в объекте одного процесса; файл JsonStorage похож на общую картотеку, которую новый сотрудник открывает заново. Новый PlannerService увидит задачу, если его сборка указывает на тот же путь. Аналогия не обещает согласование одновременной работы: два процесса могут сохранить один и тот же старый снимок, поэтому позже отдельно разберём границу последовательной работы с JSON.`}),(0,y.jsx)(u,{question:`Как проверить, что задача не осталась только в старом объекте Python?`,left:{title:`Повторно спросить тот же объект`,code:`service.add_task(...)
service.list_tasks()`,note:`Показывает, что объект видит результат. Не отделяет файл от данных, оставшихся в его памяти.`},right:{title:`Создать новый service`,code:`first = build_service()
first.add_task(...)
second = build_service()
second.list_tasks()`,note:`Проверяет, что новая сборка снова получает данные из настроенного постоянного источника.`},preferred:`right`,explanation:`Для доказательства постоянное сохранение важно пересечь границу объекта или процесса. В проекте новый build_service() должен использовать тот же путь JsonStorage, что и CLI и API.`}),(0,y.jsx)(`p`,{children:`Путь обычно задаётся в точке сборки приложения. Если он зависит только от текущей папки терминала, одинаковый запуск из разных мест может обратиться к разным файлам. Поэтому проверяйте фактическую настройку в существующем проекте, а не угадывайте её по имени data/tasks.json.`}),(0,y.jsx)(l,{statement:(0,y.jsx)(`span`,{children:`Если новый PlannerService использует тот же настроенный путь JsonStorage, чтение после перезапуска может восстановить сохранённые задачи.`}),isTrue:!0,explanation:`Новый объект не хранит старые Python-переменные. Он читает файл по настроенному пути и восстанавливает из него Task.`})]}),(0,y.jsxs)(c,{number:`03`,title:`Сервер назначает id по реальным записям`,children:[(0,y.jsx)(s,{children:`Правило id уже появилось в Persistent Planner. Здесь проверим, на какое состояние оно опирается и чего не обещает.`}),(0,y.jsx)(`p`,{children:`В текущем Planner следующий id рассчитывается от существующих записей: берётся наибольший сохранённый id и прибавляется единица. Поэтому количество задач и следующий id не всегда связаны.`}),(0,y.jsx)(`p`,{children:`Сравним два расчёта. В списке три задачи, но значения id идут с пропусками:`}),(0,y.jsx)(d,{code:`ids = [2, 7, 11]
print(len(ids) + 1, max(ids) + 1)`,output:`4 12`,hint:`Сравните число записей с наибольшим уже выданным id.`}),(0,y.jsx)(`p`,{children:`Правильное значение для действующего правила Planner зависит от максимального id. Расчёт через len() ошибся бы при пропусках. А если удалить запись с максимальным id, правило max(текущих id) + 1 может выдать это число снова. Значит, такой id уникален среди текущих задач, но не является вечным счётчиком истории.`}),(0,y.jsx)(g,{caption:`клиент сообщает данные, сервис владеет id`,code:`TaskCreate: title, priority
PlannerService: выбирает id по загруженным Task
TaskRead: возвращает назначенный id`}),(0,y.jsx)(`p`,{children:`Клиент сообщает title и priority. Сервис назначает id и начальное is_done=False; значения этих серверных полей нельзя выбрать через TaskCreate. В Pydantic лишние поля по умолчанию игнорируются, если этот режим не изменён отдельно. Поэтому переданный клиентом id не назначает задаче номер, а is_done не меняет начальный статус; сами лишние поля не означают ошибку 422. TaskRead возвращает уже назначенные значения.`}),(0,y.jsx)(`p`,{children:`Результат зависит от настройки входной модели. При extra=ignore неизвестные ключи отбрасываются, и сервис получает только объявленные поля. При extra=forbid тот же запрос остановится с 422 до вызова add_task(). Поэтому перед проверкой сверим политику TaskCreate, а не будем считать поведение лишних полей универсальным правилом. Сам серверный id в обоих случаях остаётся правилом Planner.`}),(0,y.jsx)(`p`,{children:`Правило похоже на нумерацию ячеек в архиве: чтобы выбрать следующий номер, смотрим на наибольшую занятую метку, а не считаем количество занятых ячеек. Пропуски не сбивают расчёт. Но метка не является вечным номером истории: если удалить запись с максимальным id, max(текущих id) + 1 может выдать его снова.`})]}),(0,y.jsxs)(c,{number:`04`,title:`Проверка должна пересечь границу сохранения`,children:[(0,y.jsx)(s,{children:`Один удачный ответ показывает то, что API сообщило клиенту. Чтобы проверить состояние, сравним несколько независимых наблюдений.`}),(0,y.jsx)(f,{items:[{title:`HTTP`,description:`POST возвращает 201 и фактический id. GET проверяет, что маршрут читает созданную задачу.`},{title:`CLI`,description:`Та же задача видна через старый интерфейс, который пользуется тем же Planner.`},{title:`Новый экземпляр`,description:`После остановки и повторной сборки сервиса данные снова читаются из файла.`},{title:`Тестовый путь`,description:`pytest использует tmp_path, чтобы проверить постоянное сохранение и не менять рабочий JSON ученика.`}]}),(0,y.jsx)(`p`,{children:`Эти проверки отвечают на разные вопросы. 201 проверяет контракт ответа. GET показывает путь чтения API. CLI проверяет общий проектный интерфейс. Новый экземпляр или процесс отделяет постоянный файл от состояния, которое могло остаться в памяти.`}),(0,y.jsx)(`p`,{children:`У каждого наблюдения своя роль. Перезапуск проверяет чтение после завершения прежнего процесса, а CLI подтверждает работу существующего интерфейса с сохранёнными данными. Сервисный тест в tmp_path изолирует одну операцию от рабочего JSON. Создание в нём проходит через add_task(), затем новый PlannerService читает тот же временный путь. Прямой вызов JsonStorage.save() обошёл бы выдачу id и проверил бы не весь нужный путь.`}),(0,y.jsx)(l,{statement:(0,y.jsx)(`span`,{children:`Сам по себе статус 201 доказывает, что после перезапуска задача будет прочитана из JSON.`}),isTrue:!1,explanation:`201 сообщает клиенту об успешном создании по контракту API. Persistence подтверждается чтением того же файла новым экземпляром или после перезапуска.`})]}),(0,y.jsxs)(c,{number:`05`,title:`Ошибка JsonStorage не означает пустой Planner`,children:[(0,y.jsx)(s,{children:`Ранее мы различали ошибки входа, предметного поиска и хранения. Важно не смешивать их: у каждой причины своя реакция.`}),(0,y.jsx)(f,{items:[{title:`422`,description:`Неверное тело не прошло TaskCreate. Маршрут не начал создание.`},{title:`404`,description:`Запрос корректен, но сервис не нашёл задачу с таким id.`},{title:`StorageError`,description:`Файл нельзя прочитать или восстановить. Это внутренняя проблема данных, не отсутствие задачи.`}]}),(0,y.jsx)(`p`,{children:`Если повреждённый файл превратить в пустой список, API покажет, будто Planner потерял все задачи. Следующая запись может затереть исходные данные. Ошибку формата нужно оставить заметной и не продолжать создание как будто файл был пуст.`}),(0,y.jsx)(`p`,{children:`Отсутствие одной задачи и нечитаемость всего списка возникают на разных шагах. TaskNotFoundError возможен после успешной загрузки корректного файла, когда конкретного id в нём нет. При StorageError сервис не знает, какие записи сохранены. Если свести обе причины к пустому списку или 404, клиент получит ложный ответ, а следующее изменение может скрыть повреждение.`}),(0,y.jsx)(n,{code:`def load_tasks(storage):
    try:
        return storage.load()
    except StorageError:
        return []`,question:`Почему этот обработчик опасен для существующего Planner?`,options:[`Он превращает неизвестное состояние файла в пустое и скрывает проблему, из-за чего последующая запись может затереть данные.`,`StorageError всегда нужно заменять на HTTP 404.`,`Метод load() не должен возвращать список.`],correctIndex:0,explanation:`Отсутствующая задача и невозможность прочитать весь файл имеют разные причины. StorageError нельзя маскировать под пустое состояние или 404.`}),(0,y.jsx)(g,{caption:`ответ API не может заменить результат операции`,code:`ошибка TaskCreate → 422 до endpoint
TaskNotFoundError → 404 для одного id
StorageError → видимая ошибка чтения/записи
успешный POST → 201 только после успешного создания`})]}),(0,y.jsxs)(c,{number:`06`,title:`Границы JSON-файла`,children:[(0,y.jsx)(s,{children:`JsonStorage подходит текущему небольшому Planner, но файловый контракт не обещает работу базы данных.`}),(0,y.jsx)(`p`,{children:`При последовательной работе CLI и API каждый новый вызов загружает актуальное состояние и сохраняет результат. Именно такой сценарий мы проверим. Одновременные записи уже сложнее: два процесса могут прочитать один снимок, изменить его независимо, а последняя запись затрёт изменение другой.`}),(0,y.jsx)(`p`,{children:`JSON-запись заменяет представление списка целиком, а не фиксирует отдельную задачу транзакцией. Если два процесса загрузили один исходный снимок, каждый сформирует и сохранит собственный список. Общий путь помогает при последовательной работе, но сам не объединяет такие изменения и не защищает от последней перезаписи. В этом занятии проверяем последовательный сценарий и не маскируем ограничение дополнительным временным storage.`}),(0,y.jsx)(g,{caption:`почему две одновременные записи требуют другой защиты`,code:`Процесс A: load [1] → добавляет 2 → save [1, 2]
Процесс B: load [1] → добавляет 3 → save [1, 3]

Итог при записи B последней: [1, 3]`}),(0,y.jsx)(`p`,{children:`JSON-файл не даёт автоматически транзакции и безопасную координацию нескольких писателей. Мы не добавляем блокировки и не заменяем storage базой данных в этом занятии. Для проверки достаточно выполнять действия последовательно.`}),(0,y.jsx)(m,{question:`Два клиента почти одновременно создали задачу, но одна запись пропала. Что могло произойти при чтении и сохранении общего файла?`,hint:`Подумайте, что каждый процесс успел прочитать до своей записи.`,answer:(0,y.jsx)(`p`,{children:`Оба процесса могли загрузить одинаковый старый снимок. Затем каждый сохранил собственный список, и последняя запись затёрла предыдущую. Это ограничение конкурентной работы с одним JSON-файлом.`})})]}),(0,y.jsxs)(c,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(s,{children:`Практика не реализует JsonStorage или алгоритм создания заново. Мы проверим части существующего Planner и добавим изолированное доказательство для файла.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Проследить`,description:`Проследим путь POST от TaskCreate через add_task до JsonStorage.save() и выясним, где API и CLI получают настройку общего файла.`},{title:`Проверить`,description:`Проверим две созданные задачи по фактическим id через API и CLI, в том числе после перезапуска; лишние id и is_done во входе не подменяют серверные значения.`},{title:`Защитить`,description:`Добавим тест с временным JSON: пропуски в id отличат максимум от числа записей, а новый сервис прочитает полный файл вместе с tags.`},{title:`Не скрыть`,description:`Подтвердим, что повреждённый JSON вызывает StorageError, а файл остаётся нетронутым.`}]}),(0,y.jsx)(`p`,{children:`Путь проекта остаётся один: проверка не создаёт вторую реализацию и не меняет рабочий JSON автотестами. Результат виден в фактических ответах API и CLI, а регрессия проверяется на tmp_path.`}),(0,y.jsx)(r,{points:[(0,y.jsx)(y.Fragment,{children:`TaskCreate проверяет вход, PlannerService выполняет создание, JsonStorage сохраняет Task, а TaskRead задаёт HTTP-ответ.`}),(0,y.jsx)(y.Fragment,{children:`Новый экземпляр на том же настроенном пути проверяет, что данные пережили прежний объект и процесс.`}),(0,y.jsx)(y.Fragment,{children:`Следующий id зависит от сохранённых id, а не от числа записей или догадки клиента.`}),(0,y.jsx)(y.Fragment,{children:`Повреждённое хранилище нельзя выдавать за пустой список или отсутствие одной задачи.`}),(0,y.jsx)(y.Fragment,{children:`JSON подходит текущему последовательному сценарию, но сам не решает конкурентную запись.`})]})]})]})}export{b as Lesson59};